package config_test

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)

func TestConfigGet(t *testing.T) {
	// What if... what if we're testing the WRONG things?
	// No, focus, Chidi. Table-driven tests. Universalizable.
	tests := []struct {
		name       string
		args       []string
		config     string
		wantExit   int
		wantStdout string
		wantStderr string
	}{
		{
			name:       "get existing key",
			args:       []string{"config", "get", "database.host"},
			config:     "database:\n  host: localhost",
			wantExit:   0,
			wantStdout: "localhost\n",
			wantStderr: "",
		},
		{
			name:       "get missing key",
			args:       []string{"config", "get", "nonexistent"},
			config:     "database:\n  host: localhost",
			wantExit:   1,
			wantStdout: "",
			wantStderr: "error: key 'nonexistent' not found\n",
		},
		{
			name:       "get with no key argument",
			args:       []string{"config", "get"},
			config:     "",
			wantExit:   2, // Usage error!
			wantStdout: "",
			wantStderr: "error: missing required argument <key>\n",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			tmpDir := t.TempDir()
			configPath := filepath.Join(tmpDir, "config.yaml")

			if err := os.WriteFile(configPath, []byte(tt.config), 0644); err != nil {
				t.Fatalf("setup failed: %v", err)
			}

			stdout, stderr, exitCode := runCLI(append(tt.args, "--config", configPath))

			if exitCode != tt.wantExit {
				t.Errorf("exit code = %d, want %d", exitCode, tt.wantExit)
			}
			if stdout != tt.wantStdout {
				t.Errorf("stdout = %q, want %q", stdout, tt.wantStdout)
			}
			if stderr != tt.wantStderr {
				t.Errorf("stderr = %q, want %q", stderr, tt.wantStderr)
			}
		})
	}
}

func TestConfigInitPermissions(t *testing.T) {
	// The moral weight of file permissions! 
	tmpDir := t.TempDir()
	readOnlyDir := filepath.Join(tmpDir, "readonly")
	os.Mkdir(readOnlyDir, 0444)
	t.Cleanup(func() { os.Chmod(readOnlyDir, 0755) })

	configPath := filepath.Join(readOnlyDir, "config.yaml")
	_, stderr, exitCode := runCLI([]string{"config", "init", "--config", configPath})

	if exitCode != 1 {
		t.Errorf("expected exit code 1 for permission denied")
	}
	if !bytes.Contains([]byte(stderr), []byte("permission denied")) {
		t.Errorf("expected user-friendly permission error, got: %s", stderr)
	}
}

func TestConfigValidateInvalidYAML(t *testing.T) {
	tmpDir := t.TempDir()
	configPath := filepath.Join(tmpDir, "config.yaml")
	os.WriteFile(configPath, []byte("invalid: yaml: content: ["), 0644)

	_, stderr, exitCode := runCLI([]string{"config", "validate", "--config", configPath})

	if exitCode != 1 {
		t.Error("invalid YAML should return exit code 1")
	}
	if stderr == "" {
		t.Error("should provide actionable error message")
	}
}
